metadata.sparql:
SELECT ?x ?xLabel ?cls ?clsLabel ?coord WHERE {
  ?x wdt:P31/wdt:P279* wd:Q17521458 .
  ?x wdt:P17 wd:Q17 .
  ?x wdt:P625 ?coord .
  ?x wdt:P31 ?cls .
  FILTER NOT EXISTS { ?x wdt:P31/wdt:P279* wd:Q177380 . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "ja,en". }
}
